				{
					this.Close();
				}
			}
			catch (System.Exception excep)
			{
				//UPGRADE_WARNING: (2081) Err.Number has a new behavior. More Information: https://docs.mobilize.net/vbuc/ewis/warnings#id-2081
				MessageBox.Show($"An error has occurred adding the data.{Environment.NewLine}Error: ({Information.Err().Number.ToString()}) {excep.Message}", "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
			}
		}

