			//Search for records 
			modFunctions.SearchShow("Customers", "CompanyName", "customer"); 
			break;
		case "Cancel" : 
			CancellingMode = true; 
			//Cancel edited changes 
			EditMode = false; 
			NewMode = false; 
			dcCustomers.Recordset.CancelUpdate(); 
			dcCustomers.Recordset.Requery(); 
